#include "lems/data/dataset.hpp"
#include <cassert>
#include <filesystem>
#include <fstream>
int main(){namespace fs=std::filesystem;auto root=fs::temp_directory_path()/"lems_data_test";fs::remove_all(root);fs::create_directories(root/"sequences/00/image_0");fs::create_directories(root/"sequences/00/image_1");std::ofstream(root/"sequences/00/image_0/000.png");std::ofstream(root/"sequences/00/image_1/000.png");std::ofstream(root/"sequences/00/times.txt")<<"0.5\n";auto yaml=root/"test.yaml";std::ofstream(yaml)<<"dataset_type: KITTI\ndataset_dir: .\nsequence_name: 00\nleft_camera:\n  resolution: [1241, 376]\n  intrinsics: [718.856, 718.856, 607.1928, 185.2157]\n  distortion_coefficients: [0, 0, 0, 0]\nright_camera:\n  resolution: [1241, 376]\n  intrinsics: [718.856, 718.856, 607.1928, 185.2157]\n  distortion_coefficients: [0, 0, 0, 0]\nstereo:\n  R21:\n  - [1, 0, 0]\n  - [0, 1, 0]\n  - [0, 0, 1]\n  T21: [-0.54, 0, 0]\n";auto c=lems::data::load_config(yaml);assert(c.cameras.size()==2&&c.cameras[0].K[0]==718.856&&c.stereo&&c.stereo->baseline==0.54);auto d=lems::data::open_dataset(c);auto x=d->iterate()->next();assert(x&&x->frames.size()==2&&x->timestamp_ns==500000000);fs::remove_all(root);}
